<section class="panel client-documents span-2" id="documents"><div class="panel-head"><div><h2>Documents</h2><p>Securely upload requested files</p></div></div><div class="document-layout"><div class="compact-list"><?php foreach($documents as $document):?><a class="list-row" href="<?= url('portal/documents/'.$document['id']) ?>"><span class="list-icon"><i class="fa-solid fa-file-shield"></i></span><span class="list-main"><strong><?= e($document['title']) ?></strong><small><?= e(date('d M Y, g:i A',strtotime($document['created_at']))) ?></small></span><i class="fa-solid fa-download"></i></a><?php endforeach;?><?php if(!$documents):?><div class="empty-inline">No client documents uploaded.</div><?php endif;?></div><form class="mini-form" method="post" action="<?= url('portal/documents') ?>" enctype="multipart/form-data"><?= csrf_field() ?><label>Document title<input name="title" required placeholder="e.g. Signed agreement"></label><label>Choose file<input type="file" name="document" accept=".pdf,.png,.jpg,.jpeg,.webp,.docx,.xlsx,.csv,.txt" required></label><button class="button button-primary">Upload securely</button></form></div></section>
